  Qmt = `Jenis Aktivator`,
  $mt = `Aktivator menentukan bagaimana input merespons. Apakah dengan tekan biasa, tekan panjang, atau ketukan ganda? Pilih aktivator di sini atau hapus aktivator.`,
  eht = `Tidak Ada - Hapus Aktivator`,
  tht = `Memilih opsi ini akan menghapus aktivator dan semua perintah yang ada di dalamnya.`,
  nht = `Tekan Biasa`,
  rht = `Tekan Biasa merupakan aktivator jenis default. Saat kamu menekan tombol, maka aktivator akan terus aktif sampai kamu melepasnya.`,
  iht = `Tekan Ganda`,
  aht = `Untuk mengaktifkan aktivator jenis Tekan Ganda, kamu harus mengetuk sebanyak dua kali dengan cepat pada input. Jika ditahan pada penekanan kedua, maka aktivator akan tetap aktif. Aktivator yang dapat diinterupsi yang menggunakan tombol yang sama tidak akan aktif saat tekan ganda diaktifkan dan akan dijeda hingga waktu tekan ganda berakhir.`,
  oht = `Tekan Panjang`,
  sht = `Untuk mengaktifkan aktivator jenis Tekan Panjang, kamu harus menahan tombol selama beberapa saat. Ketika waktu tekan panjang sudah lewat, aktivator akan tetap aktif hingga kamu melepaskannya kembali. Aktivator yang dapat diinterupsi menggunakan tombol yang sama tidak akan aktif saat tekan panjang diaktifkan dan akan dijeda hingga waktu tekan panjang berakhir.`,
  cht = `Mulai Tekan`,
  lht = `Aktivator Mulai Tekan akan aktif saat tombol ditekan dan akan langsung nonaktif bahkan saat tombol masih ditahan. Ini berguna khususnya saat digunakan dengan Aktivator Tekan Lepas untuk mengonversi Pengalihan ke Tahan—seperti perintah Aktifkan/Nonaktifkan Jongkok.`,
  uht = `Lepas Tekanan`,
  dht = `Aktivator Lepas Tekanan akan aktif dan nonaktif saat tombol dilepaskan.`,
  fht = `Tekan Ringan`,
  pht = `Aktivator Tekan Ringan akan aktif ketika tombol atau trigger ditekan sebagian.`,
  mht = `Analog`,
